import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.119.2';

const SUPABASE_URL='https://hulyesrekgyouibkybqn.supabase.co';
const SUPABASE_KEY='sb_publishable_-LJfTRDibZ6FLgYkuEGFEQ_INyeXlJL';
const db=createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),modalContent=document.querySelector('#modalContent');
const fotos=[
  'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=82',
  'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=82',
  'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1200&q=82',
  'https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=1200&q=82'
];
const state={session:null,staff:false,imoveis:[],favoritos:new Set(),adminTab:'resumo'};
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v||0);
const date=v=>v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—';
const photo=id=>fotos[(Number(id)-1)%fotos.length];
const toast=(msg,erro=false)=>{const el=document.querySelector('#toast');el.textContent=msg;el.style.background=erro?'#8d351c':'';el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200)};
const loading=()=>app.innerHTML='<div class="loading"><span></span><p>Consultando o Supabase...</p></div>';
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const pageHead=(eye,title,text='')=>`<div class="page-head"><p class="eyebrow">${eye}</p><h1>${title}</h1>${text?`<p>${text}</p>`:''}</div>`;
const statusLabel=s=>({DISPONIVEL:'Disponível',RESERVADO:'Reservado',VENDIDO:'Vendido',PENDENTE:'Pendente',REALIZADA:'Realizada',CANCELADA:'Cancelada',NOVO:'Novo',EM_CONTATO:'Em contato',CONCLUIDO:'Concluído'})[s]||s;

async function loadSession(){const {data}=await db.auth.getSession();state.session=data.session;state.staff=false;if(state.session){const {data:staff}=await db.rpc('equipe_atual');state.staff=staff===true;await loadFavorites()}renderNav()}
async function loadProperties(){const {data,error}=await db.from('imovel').select('*').order('destaque',{ascending:false}).order('titulo');if(error)throw error;state.imoveis=data||[]}
async function loadFavorites(){state.favoritos.clear();if(!state.session)return;const {data}=await db.from('favorito').select('imovel_id');(data||[]).forEach(x=>state.favoritos.add(Number(x.imovel_id)))}
function renderNav(){const n=document.querySelector('#sessionNav');if(!state.session)n.innerHTML='<a href="#/entrar">Entrar</a><a class="nav-pill" href="#/cadastro">Criar conta</a>';else n.innerHTML=`<a href="#/perfil">Meu perfil</a>${state.staff?'<a href="#/gestao">Gestão</a>':''}<button class="nav-pill" data-action="logout">Sair</button>`}
function card(i){const fav=state.favoritos.has(Number(i.id));return `<article class="property-card"><div class="property-image" style="background-image:url('${photo(i.id)}')"><span class="badge">${esc(i.tipo)}</span><button class="favorite ${fav?'active':''}" data-favorite="${i.id}" aria-label="Favoritar">${fav?'♥':'♡'}</button></div><div class="property-body"><div class="meta"><span>${esc(i.bairro)} · ${esc(i.cidade)}</span><span>${statusLabel(i.status)}</span></div><h3><a href="#/imovel/${i.id}">${esc(i.titulo)}</a></h3><div class="features"><span>${i.quartos} quartos</span><span>${i.banheiros} banheiros</span><span>${i.area_m2} m²</span></div><strong class="price">${money(i.preco)}</strong></div></article>`}
function cards(list){return list.length?`<div class="property-grid">${list.map(card).join('')}</div>`:'<div class="empty"><h3>Nenhum imóvel encontrado</h3><p>Altere os filtros para ampliar sua busca.</p></div>'}

async function home(){loading();if(!state.imoveis.length)await loadProperties();const disponiveis=state.imoveis.filter(i=>i.status==='DISPONIVEL');app.innerHTML=`<section class="hero"><div><p class="eyebrow">IMÓVEIS EM RIO DO SUL</p><h1>Mais que um imóvel. Um novo começo.</h1><p>Compare casas e apartamentos, salve seus favoritos e registre uma solicitação de visita diretamente pelo site.</p><div class="hero-actions"><a class="button" href="#/imoveis">Explorar imóveis</a><a class="button secondary" href="#/contato">Falar com a equipe</a></div><form class="search-box" id="heroSearch"><input name="q" placeholder="Bairro ou nome do imóvel"><select name="tipo"><option value="">Todos os tipos</option><option>CASA</option><option>SOBRADO</option><option>APARTAMENTO</option><option>TERRENO</option></select><select name="quartos"><option value="">Quartos</option><option value="2">2+</option><option value="3">3+</option><option value="4">4+</option></select><button class="button">Buscar</button></form></div><div class="hero-photo"><strong>Seu próximo endereço começa aqui.</strong></div></section><section class="stats"><div><strong>${state.imoveis.length}</strong><span>imóveis cadastrados</span></div><div><strong>${new Set(state.imoveis.map(i=>i.bairro)).size}</strong><span>bairros no catálogo</span></div><div><strong>${disponiveis.length}</strong><span>opções disponíveis</span></div></section><section class="section"><div class="section-head"><div><p class="eyebrow">SELEÇÃO DA SEMANA</p><h2>Imóveis em destaque</h2><p>Opções selecionadas com informações completas para você comparar.</p></div><a class="button secondary" href="#/imoveis">Ver catálogo</a></div>${cards(disponiveis.filter(i=>i.destaque).concat(disponiveis.filter(i=>!i.destaque)).slice(0,3))}</section><section class="section alt"><div class="section-head"><div><p class="eyebrow">UMA JORNADA MAIS SIMPLES</p><h2>Tudo em um só lugar</h2></div></div><div class="benefits"><article><b>⌕</b><h3>Busca inteligente</h3><p>Filtre por bairro, tipo, quartos e faixa de preço.</p></article><article><b>♥</b><h3>Lista de favoritos</h3><p>Guarde os imóveis que mais combinam com você.</p></article><article><b>▣</b><h3>Visitas organizadas</h3><p>Registre uma data desejada e acompanhe o status.</p></article></div></section>${calculator()}`}
function calculator(){return `<section class="section"><div class="calculator"><div><p class="eyebrow">SIMULAÇÃO EDUCACIONAL</p><h2>Planeje sua compra</h2><p>Faça uma estimativa simples de parcela. O cálculo não representa proposta de financiamento.</p><form id="calculator" class="stack">${field('Valor do imóvel','valor','number','500000','min="1"')}${field('Entrada','entrada','number','100000','min="0"')}${field('Prazo em meses','prazo','number','360','min="12" max="420"')}<button class="button">Calcular estimativa</button></form></div><div class="calculator-output"><span>Parcela aproximada sem juros</span><strong id="parcela">${money(1111)}</strong><p>Use esta referência apenas para organização inicial.</p></div></div></section>`}

async function catalog(params=new URLSearchParams()){loading();if(!state.imoveis.length)await loadProperties();app.innerHTML=`${pageHead('CATÁLOGO','Encontre o imóvel ideal','Pesquise e compare todas as opções cadastradas.') }<section class="section" style="padding-top:10px"><form class="filter-panel" id="filters"><input name="q" value="${esc(params.get('q')||'')}" placeholder="Buscar por nome, bairro ou cidade"><select name="tipo"><option value="">Todos os tipos</option>${['CASA','SOBRADO','APARTAMENTO','TERRENO'].map(x=>`<option ${params.get('tipo')===x?'selected':''}>${x}</option>`).join('')}</select><select name="quartos"><option value="">Quartos</option>${[1,2,3,4].map(x=>`<option value="${x}" ${params.get('quartos')==x?'selected':''}>${x}+</option>`).join('')}</select><input name="preco" type="number" value="${esc(params.get('preco')||'')}" placeholder="Preço máximo"><select name="status"><option value="">Todos os status</option><option value="DISPONIVEL">Disponível</option><option value="RESERVADO">Reservado</option><option value="VENDIDO">Vendido</option></select></form><p id="resultCount"></p><div id="catalogGrid"></div></section>`;filterCatalog()}
function filterCatalog(){const f=new FormData(document.querySelector('#filters'));let list=[...state.imoveis];const q=String(f.get('q')||'').toLowerCase(),tipo=f.get('tipo'),quartos=Number(f.get('quartos')||0),preco=Number(f.get('preco')||0),status=f.get('status');if(q)list=list.filter(i=>`${i.titulo} ${i.bairro} ${i.cidade}`.toLowerCase().includes(q));if(tipo)list=list.filter(i=>i.tipo===tipo);if(quartos)list=list.filter(i=>i.quartos>=quartos);if(preco)list=list.filter(i=>Number(i.preco)<=preco);if(status)list=list.filter(i=>i.status===status);document.querySelector('#resultCount').textContent=`${list.length} imóvel(is) encontrado(s)`;document.querySelector('#catalogGrid').innerHTML=cards(list)}

async function detail(id){loading();let i=state.imoveis.find(x=>Number(x.id)===Number(id));if(!i){const {data}=await db.from('imovel').select('*').eq('id',id).maybeSingle();i=data}if(!i)return notFound();if(state.session)db.from('historico_navegacao').insert({auth_id:state.session.user.id,imovel_id:i.id}).then(()=>{});app.innerHTML=`<section class="detail"><div class="detail-image" style="background-image:url('${photo(i.id)}')"></div><aside class="detail-panel"><div class="meta"><span>${esc(i.bairro)}, ${esc(i.cidade)}</span><span>${statusLabel(i.status)}</span></div><h1>${esc(i.titulo)}</h1><strong class="price">${money(i.preco)}</strong><div class="detail-features"><div><strong>${i.quartos}</strong><br>quartos</div><div><strong>${i.banheiros}</strong><br>banheiros</div><div><strong>${i.vagas}</strong><br>vagas</div><div><strong>${i.area_m2}</strong><br>m²</div></div><div class="stack"><button class="button" data-visit="${i.id}" ${i.status!=='DISPONIVEL'?'disabled':''}>Solicitar visita</button><button class="button secondary" data-favorite="${i.id}">${state.favoritos.has(Number(i.id))?'Remover dos favoritos':'Adicionar aos favoritos'}</button></div></aside><div class="detail-copy"><article class="panel"><p class="eyebrow">SOBRE O IMÓVEL</p><h2>Detalhes da propriedade</h2><p>${esc(i.descricao)}</p></article><article class="panel"><p class="eyebrow">LOCALIZAÇÃO</p><h2>${esc(i.endereco)}</h2><p>${esc(i.bairro)} · ${esc(i.cidade)}</p><a class="button secondary" href="#/contato?imovel=${i.id}">Perguntar sobre este imóvel</a></article></div></section>`}
async function favoritesPage(){loading();if(!state.session){app.innerHTML=authRequired('Entre para sincronizar seus favoritos em qualquer dispositivo.');return}await loadFavorites();if(!state.imoveis.length)await loadProperties();const list=state.imoveis.filter(i=>state.favoritos.has(Number(i.id)));app.innerHTML=`${pageHead('SUA SELEÇÃO','Imóveis favoritos','Revise as opções salvas e solicite uma visita quando decidir.')}<section class="section" style="padding-top:20px">${cards(list)}</section>`}

function authRequired(msg){return `<div class="auth-wrap"><div><p class="eyebrow">ÁREA PROTEGIDA</p><h1>Entre para continuar.</h1><p>${msg}</p></div><div class="auth-card"><a class="button" href="#/entrar">Fazer login</a></div></div>`}
function authPage(register=false){app.innerHTML=`<div class="auth-wrap"><div><p class="eyebrow">ÁREA DO CLIENTE</p><h1>${register?'Crie sua conta.':'Bem-vindo de volta.'}</h1><p>Acompanhe favoritos, histórico e solicitações de visita.</p></div><form class="auth-card stack" id="authForm">${register?field('Nome completo','nome','text','','required maxlength="100"'):''}${field('E-mail','email','email','','required')}${field('Senha','senha','password','','required minlength="'+(register?8:1)+'"')}<button class="button">${register?'Criar conta':'Entrar'}</button><a href="${register?'#/entrar':'#/cadastro'}">${register?'Já tenho uma conta':'Ainda não tenho conta'}</a><div id="authMessage"></div></form></div>`;document.querySelector('#authForm').dataset.register=register}
async function profile(){loading();if(!state.session){app.innerHTML=authRequired('Seu perfil reúne dados pessoais, histórico e visitas.');return}const uid=state.session.user.id;const [{data:cliente},{data:historico},{data:visitas}]=await Promise.all([db.from('cliente').select('*').eq('auth_id',uid).maybeSingle(),db.from('vw_historico_navegacao').select('*').order('consultado_em',{ascending:false}).limit(12),db.from('vw_visitas').select('*').order('inicio',{ascending:false}).limit(20)]);app.innerHTML=`${pageHead('MINHA CONTA',`Olá, ${esc((cliente?.nome||state.session.user.email).split(' ')[0])}.`,'Edite seus dados e acompanhe sua jornada de busca.')}<section class="section profile-grid" style="padding-top:20px"><form class="panel stack" id="profileForm"><h2>Dados pessoais</h2>${field('Nome','nome','text',cliente?.nome||'','required')}${field('E-mail','email','email',cliente?.email||state.session.user.email,'disabled')}${field('Telefone','telefone','tel',cliente?.telefone||'')}<button class="button">Salvar dados</button></form><div class="stack"><section class="panel"><h2>Solicitações de visita</h2>${table(['Imóvel','Corretor','Data','Status'],(visitas||[]).map(v=>[v.imovel,v.corretor,date(v.inicio),statusLabel(v.status)]))}</section><section class="panel"><h2>Últimos imóveis consultados</h2><div class="history">${(historico||[]).length?(historico||[]).map(h=>`<a href="#/imovel/${h.imovel_id}"><span><strong>${esc(h.titulo)}</strong><br><small>${esc(h.bairro)}</small></span><span>${date(h.consultado_em)}</span></a>`).join(''):'<p>Nenhuma consulta registrada.</p>'}</div></section></div></section>`}

function contact(params=new URLSearchParams()){const imovel=params.get('imovel');app.innerHTML=`${pageHead('FALE CONOSCO','Vamos conversar sobre seu próximo imóvel.','Envie uma mensagem. A equipe visualizará o contato no painel administrativo.')}<section class="section contact-grid" style="padding-top:20px"><div class="stack"><article class="panel"><strong>Telefone</strong><p>(47) 3521-2026</p></article><article class="panel"><strong>E-mail</strong><p>contato@horizonte.test</p></article><article class="panel"><strong>Atendimento</strong><p>Segunda a sexta, das 8h às 18h.</p></article></div><form class="panel stack" id="contactForm">${field('Nome','nome','text','','required maxlength="100"')}${field('E-mail','email','email',state.session?.user?.email||'','required')}${field('Telefone','telefone','tel','','maxlength="25"')}<label class="field">Mensagem<textarea name="mensagem" maxlength="1200" required placeholder="Conte o que você procura..."></textarea></label><input type="hidden" name="imovel_id" value="${esc(imovel||'')}"><button class="button">Enviar mensagem</button></form></section>`}

async function admin(){loading();if(!state.session||!state.staff){app.innerHTML=authRequired('Esta área é exclusiva da equipe administrativa.');return}if(!state.imoveis.length)await loadProperties();const [{data:visitas},{data:leads},{data:usuarios},{data:ranking}]=await Promise.all([db.from('vw_visitas').select('*').order('inicio',{ascending:false}).limit(100),db.from('contato_lead').select('*').order('criado_em',{ascending:false}),db.rpc('listar_usuarios_admin'),db.from('vw_ranking').select('*').order('total',{ascending:false})]);const data={visitas:visitas||[],leads:leads||[],usuarios:usuarios||[],ranking:ranking||[]};app.innerHTML=`${pageHead('PAINEL ADMINISTRATIVO','Gestão da imobiliária','Cadastros, atendimento e indicadores diretamente no Supabase.')}<section class="section" style="padding-top:10px"><div class="tabs">${[['resumo','Resumo'],['imoveis','Imóveis'],['visitas','Visitas'],['contatos','Contatos'],['usuarios','Contas']].map(([k,l])=>`<button class="tab ${state.adminTab===k?'active':''}" data-admin-tab="${k}">${l}</button>`).join('')}</div><div id="adminContent"></div></section>`;renderAdmin(data)}
function renderAdmin(data){const root=document.querySelector('#adminContent');if(state.adminTab==='resumo')root.innerHTML=`<div class="dashboard-grid"><div class="metric"><span>Imóveis</span><strong>${state.imoveis.length}</strong></div><div class="metric"><span>Visitas pendentes</span><strong>${data.visitas.filter(v=>v.status==='PENDENTE').length}</strong></div><div class="metric"><span>Novos contatos</span><strong>${data.leads.filter(v=>v.status==='NOVO').length}</strong></div></div><section class="panel" style="margin-top:20px"><h2>Ranking de imóveis visitados</h2>${table(['Imóvel','Visitas realizadas'],data.ranking.map(x=>[x.titulo,x.total]))}</section>`;else if(state.adminTab==='imoveis')root.innerHTML=`<div class="section-head"><div><h2>Catálogo</h2><p>Edite preço, descrição, características e status.</p></div></div>${table(['Imóvel','Bairro','Preço','Status','Ações'],state.imoveis.map(i=>[i.titulo,i.bairro,money(i.preco),statusLabel(i.status),`<button class="button small" data-edit-property="${i.id}">Editar</button>`]))}`;else if(state.adminTab==='visitas')root.innerHTML=table(['Cliente','Imóvel','Data','Corretor','Status','Ações'],data.visitas.map(v=>[v.cliente,v.imovel,date(v.inicio),v.corretor,statusLabel(v.status),v.status==='PENDENTE'?`<button class="button small" data-visit-status="${v.id}" data-status="REALIZADA">Realizar</button> <button class="button secondary small" data-visit-status="${v.id}" data-status="CANCELADA">Cancelar</button>`:'—']));else if(state.adminTab==='contatos')root.innerHTML=table(['Nome','E-mail','Mensagem','Data','Status'],data.leads.map(l=>[l.nome,l.email,l.mensagem,date(l.criado_em),`<select data-lead-status="${l.id}">${['NOVO','EM_CONTATO','CONCLUIDO'].map(s=>`<option value="${s}" ${s===l.status?'selected':''}>${statusLabel(s)}</option>`).join('')}</select>`]));else root.innerHTML=`<div class="notice">A nova senha deve ter pelo menos oito caracteres.</div>${table(['Nome','E-mail','Criada em','Alterar senha'],data.usuarios.map(u=>[u.nome,u.email,date(u.criado_em),`<form class="inline-password" data-user="${u.id}"><input name="senha" type="password" minlength="8" placeholder="Nova senha" required> <button class="button small">Salvar</button></form>`]))}`}
function table(headers,rows){if(!rows.length)return'<div class="empty">Nenhum registro encontrado.</div>';return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}

async function toggleFavorite(id){if(!state.session){location.hash='#/entrar';toast('Entre para salvar favoritos.');return}id=Number(id);if(state.favoritos.has(id)){const {error}=await db.from('favorito').delete().eq('auth_id',state.session.user.id).eq('imovel_id',id);if(error)return toast(error.message,true);state.favoritos.delete(id);toast('Removido dos favoritos.')}else{const {error}=await db.from('favorito').insert({auth_id:state.session.user.id,imovel_id:id});if(error)return toast(error.message,true);state.favoritos.add(id);toast('Imóvel salvo nos favoritos.')}route()}
async function visitModal(id){if(!state.session){location.hash='#/entrar';return}const i=state.imoveis.find(x=>Number(x.id)===Number(id));const {data:cliente}=await db.from('cliente').select('id').eq('auth_id',state.session.user.id).maybeSingle();if(!cliente)return toast('Perfil de cliente não encontrado.',true);modalContent.innerHTML=`<p class="eyebrow">SOLICITAR VISITA</p><h2>${esc(i.titulo)}</h2><form class="stack" id="visitForm" data-client="${cliente.id}" data-property="${i.id}" data-price="${i.preco}">${field('Data e hora desejadas','inicio','datetime-local','','required')}<p>O pedido será registrado como pendente e a equipe poderá confirmar os detalhes.</p><button class="button">Registrar solicitação</button></form>`;modal.showModal()}
async function propertyModal(id){const i=state.imoveis.find(x=>Number(x.id)===Number(id));const {data:owners}=await db.from('proprietario').select('id,nome').order('nome');modalContent.innerHTML=`<p class="eyebrow">GESTÃO DE IMÓVEL</p><h2>Editar cadastro</h2><form class="stack" id="propertyForm" data-id="${i.id}">${field('Título','titulo','text',i.titulo,'required')}${field('Preço','preco','number',i.preco,'required min="1"')}<label class="field">Descrição<textarea name="descricao" required>${esc(i.descricao)}</textarea></label>${field('Bairro','bairro','text',i.bairro,'required')}${field('Cidade','cidade','text',i.cidade,'required')}${field('Endereço','endereco','text',i.endereco,'required')}<div class="filter-panel">${field('Quartos','quartos','number',i.quartos,'required')}${field('Banheiros','banheiros','number',i.banheiros,'required')}${field('Vagas','vagas','number',i.vagas,'required')}${field('Área m²','area_m2','number',i.area_m2,'required')}</div><label class="field">Tipo<select name="tipo">${['CASA','SOBRADO','APARTAMENTO','TERRENO'].map(x=>`<option ${x===i.tipo?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Proprietário<select name="proprietario_id">${(owners||[]).map(o=>`<option value="${o.id}" ${o.id===i.proprietario_id?'selected':''}>${esc(o.nome)}</option>`).join('')}</select></label><label class="field">Status<select name="status">${['DISPONIVEL','RESERVADO','VENDIDO'].map(x=>`<option ${x===i.status?'selected':''}>${statusLabel(x)}</option>`).join('')}</select></label><label><input name="destaque" type="checkbox" ${i.destaque?'checked':''}> Imóvel em destaque</label><button class="button">Salvar no Supabase</button></form>`;modal.showModal()}

async function route(){document.querySelector('#mainNav').classList.remove('open');loading();const raw=location.hash.slice(2)||'inicio', [path,query='']=raw.split('?'),parts=path.split('/');try{if(parts[0]==='inicio')await home();else if(parts[0]==='imoveis')await catalog(new URLSearchParams(query));else if(parts[0]==='imovel')await detail(parts[1]);else if(parts[0]==='favoritos')await favoritesPage();else if(parts[0]==='entrar')authPage(false);else if(parts[0]==='cadastro')authPage(true);else if(parts[0]==='perfil')await profile();else if(parts[0]==='contato')contact(new URLSearchParams(query));else if(parts[0]==='gestao')await admin();else notFound()}catch(e){console.error(e);app.innerHTML=`${pageHead('ERRO','Não foi possível carregar esta página.')}<section class="section"><div class="notice error">${esc(e.message||'Falha de conexão com o Supabase.')}</div></section>`}window.scrollTo({top:0,behavior:'instant'})}
function notFound(){app.innerHTML=`${pageHead('404','Página não encontrada.')}<section class="section"><a class="button" href="#/inicio">Voltar ao início</a></section>`}

document.addEventListener('click',async e=>{const fav=e.target.closest('[data-favorite]');if(fav)return toggleFavorite(fav.dataset.favorite);const visit=e.target.closest('[data-visit]');if(visit)return visitModal(visit.dataset.visit);const edit=e.target.closest('[data-edit-property]');if(edit)return propertyModal(edit.dataset.editProperty);const tab=e.target.closest('[data-admin-tab]');if(tab){state.adminTab=tab.dataset.adminTab;return admin()}const vs=e.target.closest('[data-visit-status]');if(vs){const {error}=await db.from('visita').update({status:vs.dataset.status}).eq('id',vs.dataset.visitStatus);if(error)toast(error.message,true);else{toast('Status atualizado.');admin()}return}if(e.target.matches('[data-action="logout"]')){await db.auth.signOut();state.session=null;state.staff=false;renderNav();location.hash='#/inicio'}if(e.target.matches('[data-close]'))modal.close()});
document.addEventListener('change',async e=>{if(e.target.closest('#filters'))filterCatalog();if(e.target.matches('[data-lead-status]')){const {error}=await db.from('contato_lead').update({status:e.target.value}).eq('id',e.target.dataset.leadStatus);toast(error?error.message:'Contato atualizado.',!!error)}});
document.addEventListener('input',e=>{if(e.target.closest('#filters'))filterCatalog()});
document.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='heroSearch'){const p=new URLSearchParams();for(const [k,v] of f)if(v)p.set(k,v);location.hash='#/imoveis?'+p;return}if(e.target.id==='calculator'){const v=Number(f.get('valor')),en=Number(f.get('entrada')),p=Number(f.get('prazo'));document.querySelector('#parcela').textContent=money(Math.max(0,v-en)/p);return}if(e.target.id==='authForm'){const register=e.target.dataset.register==='true';let result;if(register)result=await db.auth.signUp({email:f.get('email'),password:f.get('senha'),options:{data:{nome:f.get('nome')}}});else result=await db.auth.signInWithPassword({email:f.get('email'),password:f.get('senha')});const msg=document.querySelector('#authMessage');if(result.error)msg.innerHTML=`<div class="notice error">${esc(result.error.message)}</div>`;else if(register)msg.innerHTML='<div class="notice">Conta criada. Confira o e-mail antes de entrar.</div>';else{await loadSession();location.hash='#/perfil'}return}if(e.target.id==='profileForm'){const {error}=await db.from('cliente').update({nome:f.get('nome'),telefone:f.get('telefone')||null}).eq('auth_id',state.session.user.id);toast(error?error.message:'Perfil atualizado.',!!error);return}if(e.target.id==='contactForm'){const body=Object.fromEntries(f);body.auth_id=state.session?.user?.id||null;body.imovel_id=body.imovel_id?Number(body.imovel_id):null;const {error}=await db.from('contato_lead').insert(body);if(error)toast(error.message,true);else{e.target.reset();toast('Mensagem enviada para a equipe.')}return}if(e.target.id==='visitForm'){const body={cliente_id:Number(e.target.dataset.client),imovel_id:Number(e.target.dataset.property),horario_id:null,inicio:new Date(f.get('inicio')).toISOString(),preco_registrado:Number(e.target.dataset.price),status:'PENDENTE'};const {error}=await db.from('visita').insert(body);if(error)toast(error.message,true);else{modal.close();toast('Solicitação registrada.');location.hash='#/perfil'}return}if(e.target.id==='propertyForm'){const body=Object.fromEntries(f);['preco','quartos','banheiros','vagas','area_m2','proprietario_id'].forEach(k=>body[k]=Number(body[k]));body.destaque=f.get('destaque')==='on';const {error}=await db.from('imovel').update(body).eq('id',e.target.dataset.id);if(error)toast(error.message,true);else{modal.close();await loadProperties();toast('Imóvel atualizado.');admin()}return}if(e.target.matches('.inline-password')){const {error}=await db.rpc('alterar_senha_usuario',{p_usuario:e.target.dataset.user,p_nova_senha:f.get('senha')});toast(error?error.message:'Senha alterada.',!!error);if(!error)e.target.reset()}});
document.querySelector('#menuButton').addEventListener('click',e=>{const nav=document.querySelector('#mainNav');nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',nav.classList.contains('open'))});
modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
window.addEventListener('hashchange',route);
db.auth.onAuthStateChange(()=>setTimeout(async()=>{await loadSession();route()},0));
await loadSession();await route();
